function GooglePADView:SetBgImgBySdk()
    local isAndroid = HotfixHelper:IsAndroidPlatform()
    HotfixHelper:SetGameObjectActive("bgImg", self.gameObject, CS.GameProperties:Get().UseSDKType == SDKChannelNames.IsUseQuickSDK or CS.GameProperties:Get().UseSDKType == SDKChannelNames.IsUseHuaWeiSDK )
    HotfixHelper:SetGameObjectActive("bgImg1", self.gameObject, CS.GameProperties:Get().UseSDKType == SDKChannelNames.IsUseGoogleSDK or  CS.GameProperties:Get().UseSDKType == SDKChannelNames.IsUseGoogleSDK4)
    HotfixHelper:SetGameObjectActive("bgImg2", self.gameObject, (CS.GameProperties:Get().UseSDKType == SDKChannelNames.IsUseUltraSdk2 or CS.GameProperties:Get().UseSDKType == SDKChannelNames.IsUseUltraSdk3 or CS.GameProperties:Get().UseSDKType == SDKChannelNames.IsUseUltraSdk4 or CS.GameProperties:Get().UseSDKType == SDKChannelNames.IsUseUltraSdk5) and isAndroid )
    HotfixHelper:SetGameObjectActive("bgImg3", self.gameObject, (CS.GameProperties:Get().UseSDKType == SDKChannelNames.IsUseUltraSdk2 or  CS.GameProperties:Get().UseSDKType == SDKChannelNames.IsUseUltraSdk3 or CS.GameProperties:Get().UseSDKType == SDKChannelNames.IsUseUltraSdk4 or CS.GameProperties:Get().UseSDKType == SDKChannelNames.IsUseUltraSdk5) and not isAndroid)
    HotfixHelper:SetGameObjectActive("bgImgcn", self.gameObject,CS.GameProperties:Get().UseSDKType == SDKChannelNames.IsUseQuickSDKChina or not CS.GameProperties:Get().IsUseSDK)

end

