--{{{更新进度
---@param request PlayAssetPackRequest
function GooglePADView:OpenUpdateSlider(request)
    HotfixHelper:SetGameObjectActive("UpdateAsset", self.gameObject, true)
    HotfixHelper:SetSlider(self.Slider, request.DownloadProgress)
    self.progressSlider = HotfixHelper:SetSliderAniByFinishCallback(self.progressSlider, function()
    end)
    HotfixHelper:SetGameObjectActive("downLoadText", self.gameObject, false)
end

---@param request PlayAssetPackRequest
function GooglePADView:UpdateExplain(request)
    local IsTip=true
    local IsFailed=false
    local str = ""
    local str1 = request.AssetPackName==GooglePackAssetName.FastFollow and HotfixHelper:GetStringById(HotfixString.GoogleAssetPackFastFollow) or HotfixHelper:GetStringById(HotfixString.GoogleAssetPackOnDemand)
    local str2 =""
    if request.Status == AssetDeliveryStatus.Pending then
        IsTip = false
        str = HotfixHelper:GetStringById(HotfixString.GoogleAssetPackPending)
    elseif  request.Status == AssetDeliveryStatus.Retrieving then
        IsTip = false
        str = HotfixHelper:GetStringById(HotfixString.GoogleAssetPackRetrieving)
    elseif request.Status == AssetDeliveryStatus.Available  then
        str = HotfixHelper:GetStringById(HotfixString.GoogleAssetPackAvailable)
    elseif request.Status == AssetDeliveryStatus.Failed  then
        IsFailed=true
        str = HotfixHelper:GetStringById(HotfixString.GoogleAssetPackFailed)
    elseif request.Status == AssetDeliveryStatus.WaitingForWifi  then
        str = HotfixHelper:GetStringById(HotfixString.GoogleAssetPackWaitingForWifi)
    end
    if IsFailed then
        print(" request.Error  : "..tostring(request.Error))
        if request.Error == AssetDeliveryErrorCode.AppUnavailable then
            str2 = HotfixHelper:GetStringById(HotfixString.GoogleErrorAppUnavailable) ---请求应用程序不可用
        elseif request.Error == AssetDeliveryErrorCode.BundleUnavailable then
            str2 = HotfixHelper:GetStringById(HotfixString.GoogleErrorBundleUnavailable) ---请求的资源包不可用
        elseif request.Error == AssetDeliveryErrorCode.NetworkError then
            str2 = HotfixHelper:GetStringById(HotfixString.GoogleErrorNetworkError) ---网络错误。无法获取资产包详细信息
        elseif request.Error == AssetDeliveryErrorCode.AccessDenied then
            str2 = HotfixHelper:GetStringById(HotfixString.GoogleErrorAccessDenied) ---在当前设备环境下不允许下载，例如应用程序在后台运行
        elseif request.Error == AssetDeliveryErrorCode.InsufficientStorage then
            str2 = HotfixHelper:GetStringById(HotfixString.GoogleErrorInsufficientStorage) ---由于存储空间不足，安装资产包失败
        elseif request.Error == AssetDeliveryErrorCode.AssetBundleLoadingError then
            str2 = HotfixHelper:GetStringById(HotfixString.GoogleErrorAssetBundleLoadingError) ---AssetBundle加载失败
        elseif request.Error == AssetDeliveryErrorCode.Canceled then
            str2 = HotfixHelper:GetStringById(HotfixString.GoogleErrorCanceled) ---下载被取消，可能是由于用户取消了下载通知
        elseif request.Error == AssetDeliveryErrorCode.InternalError then
            str2 = HotfixHelper:GetStringById(HotfixString.GoogleErrorInternalError) ---检索资产包时出现未知错误
        elseif request.Error == AssetDeliveryErrorCode.PlayStoreNotFound then
            str2 = HotfixHelper:GetStringById(HotfixString.GoogleErrorPlayStoreNotFound) ---应用程序要么没有安装或者不是正式版本
        elseif request.Error == AssetDeliveryErrorCode.NetworkUnrestricted then
            str2 = HotfixHelper:GetStringById(HotfixString.GoogleErrorNetworkUnrestricted) ---下载被取消，可能是由于用户取消了下载通知
        elseif request.Error == AssetDeliveryErrorCode.AppNotOwned then
            str2 = HotfixHelper:GetStringById(HotfixString.GoogleErrorAppNotOwned) ---该应用程序不属于该设备上的任何用户。只有从Google商店获得的，才属于该设备
        end
    end
    self:SetStartLoadTextText(str2)
    if IsTip then
        self:SetTips(string.format(str,str1))
        self:SetDownLoadText("")
    else
        self:SetTips("")
        self:SetDownLoadText(string.format(str,str1))
    end

end

function GooglePADView:CloseUpdateSlider()
    HotfixHelper:SetGameObjectActive("UpdateAsset", self.gameObject, false)
end

---@param request PlayAssetPackRequest
function GooglePADView:AssetPackUpdate(request)
    if self.cs_AssetPackUpdate ~= nil then
        cs_coroutine.stop(self.cs_AssetPackUpdate)
    end
    --print("  request.TotalBytesToDownload "..tostring(request.TotalBytesToDownload))
    self:StartDownload(request)
    self:UpdateProgress(0,0)
    self.cs_AssetPackUpdate = cs_coroutine.start(function()
        while not request.IsDone  do
            self:UpdateExplain(request)
            if request.Status == AssetDeliveryStatus.Retrieving then
                local totalBytes = tonumber(request.TotalBytesToDownload)
                if totalBytes>0 then
                    local max = totalBytes / 1024 /1024
                    local value = max * request.DownloadProgress
                    self:UpdateProgress(value,max, request.DownloadProgress)
                end
            end
            coroutine.yield()
        end
        self:UpdateExplain(request)
        local totalBytes = tonumber(request.TotalBytesToDownload)
        if totalBytes>0 then
            local max = totalBytes / 1024 /1024
            local value = max * request.DownloadProgress
            self:UpdateProgress(value,max, request.DownloadProgress)
        end
    end)
end

function GooglePADView:UpdateProgress(value, max,per)
    per = per==nil and 0 or per
    local formatStr = max >= 0.1 and "%0.2fMB/%0.2fMB" or "%dKB/%dKB"
    if max < 0.1 then
        max = math.floor(max * 1024)
        value = math.floor(value * 1024)
    end
    if max<0.0001 then
        self:SetProgressText("")
    else
        value = value <0.0001 and 0 or value
        local str = string.format(formatStr, value, max)
        self:SetProgressText(str)
    end
    --print("  GooglePADView  self.progressSlider     "..per)
    HotfixHelper:SetSliderAniByGo(self.progressSlider, per)
end
--}}}

--{{{更新完成
---@param request PlayAssetPackRequest
function GooglePADView:DownloadComplete(request)
    if self.cs_AssetPackUpdate ~= nil then
        cs_coroutine.stop(self.cs_AssetPackUpdate)
    end
    local str = HotfixHelper:GetStringById(HotfixString.GoogleAssetPackAvailable)
    local str1 = request.AssetPackName==GooglePackAssetName.FastFollow and HotfixHelper:GetStringById(HotfixString.GoogleAssetPackFastFollow) or HotfixHelper:GetStringById(HotfixString.GoogleAssetPackOnDemand)
    local str2 =""
    self:SetStartLoadTextText(str2)
    self:SetTips(string.format(str,str1))
    self:SetDownLoadText("")
end
